<?php require dirname(__DIR__).'/bootstrap.php';header('Cache-Control: no-store');if(!isset($_SESSION['admin']))go('login.php');
$tabs=['dashboard'=>'Tổng quan','profile'=>'Hồ sơ cá nhân','projects'=>'Dự án','skills'=>'Kỹ năng','messages'=>'Tin nhắn','password'=>'Đổi mật khẩu'];$tab=$_GET['tab']??'dashboard';if(!isset($tabs[$tab]))$tab='dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){check();try{$act=val('action',40);$id=(int)($_POST['id']??0);
if($act==='logout'){$_SESSION=[];session_destroy();go('login.php');}
if($act==='profile'){$name=val('name',150);$email=val('email');if(!$name||($email&&!filter_var($email,FILTER_VALIDATE_EMAIL)))throw new RuntimeException('Tên và email chưa hợp lệ.');q('UPDATE profile SET name=?,role=?,bio=?,email=?,location=?,github=? WHERE id=1',[$name,val('role'),val('bio',10000),$email,val('location'),urlval('github')]);}
if($act==='projects'){$title=val('title',150);if(!$title)throw new RuntimeException('Vui lòng nhập tên dự án.');$v=[$title,val('category',80),val('description',10000),val('tech'),urlval('url'),isset($_POST['published'])?1:0];if($id){$v[]=$id;q('UPDATE projects SET title=?,category=?,description=?,tech=?,url=?,published=? WHERE id=?',$v);}else q('INSERT INTO projects(title,category,description,tech,url,published) VALUES(?,?,?,?,?,?)',$v);}
if($act==='skills'){$name=val('name',100);if(!$name)throw new RuntimeException('Vui lòng nhập tên kỹ năng.');if($id)q('UPDATE skills SET name=?,category=? WHERE id=?',[$name,val('category',80),$id]);else q('INSERT INTO skills(name,category) VALUES(?,?)',[$name,val('category',80)]);}
if($act==='delete'&&in_array($tab,['projects','skills','messages'],true))q("DELETE FROM $tab WHERE id=?",[$id]);
if($act==='read')q('UPDATE messages SET is_read=1 WHERE id=?',[$id]);
if($act==='password'){$u=q('SELECT * FROM admins WHERE id=?',[$_SESSION['admin']])->fetch();$pw=val('new_password',200);if(!password_verify((string)($_POST['old_password']??''),$u['password_hash'])||strlen($pw)<12||$pw!==($_POST['confirm_password']??''))throw new RuntimeException('Kiểm tra mật khẩu hiện tại, xác nhận và độ dài tối thiểu 12 ký tự.');q('UPDATE admins SET password_hash=? WHERE id=?',[password_hash($pw,PASSWORD_DEFAULT),$_SESSION['admin']]);session_regenerate_id(true);}
flash('Đã cập nhật thành công.');}catch(RuntimeException $e){flash($e->getMessage());}go('index.php?tab='.$tab);}
head($tabs[$tab].' · Admin','../');?><div class="adminlayout"><aside><a class="brand" href="../">N<span>↗</span></a><p class="eyebrow">CONTENT STUDIO</p><nav><?php foreach($tabs as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=e($v)?></a><?php endforeach;?></nav><a href="../" target="_blank" rel="noopener">Xem website ↗</a><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button class="secondary">Đăng xuất</button></form></aside><main class="adminmain"><p class="eyebrow">WORKSPACE / <?=e(strtoupper($tab))?></p><h1><?=e($tabs[$tab])?></h1><?php notice();
function field($key,$label,$value='',$type='text',$max=255){echo '<label>'.e($label);if($type==='textarea')echo '<textarea name="'.e($key).'" rows="5" maxlength="'.$max.'">'.e($value).'</textarea>';else echo '<input type="'.e($type).'" name="'.e($key).'" maxlength="'.$max.'" value="'.e($value).'">';echo '</label>';}
function actionform($action,$id,$label){echo '<form method="post" class="inline">'.csrf().'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="id" value="'.(int)$id.'"><button class="secondary">'.$label.'</button></form>';}
if($tab==='dashboard'):?><p>Quản lý nội dung website của bạn từ một nơi.</p><div class="stats"><?php foreach(['projects'=>'Dự án','skills'=>'Kỹ năng','messages'=>'Tin nhắn'] as $t=>$label):?><a class="card" href="?tab=<?=$t?>"><strong><?=q("SELECT COUNT(*) FROM $t")->fetchColumn()?></strong><?=e($label)?></a><?php endforeach;?></div><div class="panel"><h2>Bắt đầu với hồ sơ của bạn</h2><p>Cập nhật giới thiệu, thêm kỹ năng và đăng dự án đầu tiên. Nội dung được lưu trong MySQL và hiển thị trên website.</p><a class="button" href="?tab=profile">Chỉnh sửa hồ sơ →</a></div>
<?php elseif($tab==='profile'):$p=q('SELECT * FROM profile WHERE id=1')->fetch();?><form method="post" class="panel"><?=csrf()?><input type="hidden" name="action" value="profile"><?php field('name','Họ tên',$p['name'],'text',150);field('role','Vai trò',$p['role']);field('bio','Giới thiệu',$p['bio'],'textarea',10000);field('email','Email công khai',$p['email'],'email');field('location','Địa điểm',$p['location']);field('github','Liên kết GitHub',$p['github'],'url',500);?><button>Lưu hồ sơ</button></form>
<?php elseif(in_array($tab,['projects','skills'],true)):$edit=null;if(isset($_GET['edit']))$edit=q("SELECT * FROM $tab WHERE id=?",[(int)$_GET['edit']])->fetch();?><div class="panel"><h2><?=$edit?'Chỉnh sửa':'Thêm mới'?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="<?=$tab?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><?php if($tab==='projects'){field('title','Tên dự án',$edit['title']??'','text',150);field('category','Lĩnh vực',$edit['category']??'','text',80);field('description','Mô tả',$edit['description']??'','textarea',10000);field('tech','Công nghệ',$edit['tech']??'');field('url','Link demo hoặc mã nguồn',$edit['url']??'','url',500);echo '<label class="check"><input type="checkbox" name="published" '.((!$edit||$edit['published'])?'checked':'').'> Hiển thị công khai</label>';}else{field('name','Tên kỹ năng',$edit['name']??'','text',100);field('category','Nhóm kỹ năng',$edit['category']??'','text',80);} ?><button>Lưu nội dung</button> <a href="?tab=<?=$tab?>">Hủy chỉnh sửa</a></form></div><div class="panel"><h2>Danh sách nội dung</h2><?php $rows=q("SELECT * FROM $tab ORDER BY id DESC")->fetchAll();if(!$rows)echo '<p>Chưa có nội dung. Thêm mục đầu tiên ở trên.</p>';foreach($rows as $r):?><div class="row"><div><strong><?=e($r['title']??$r['name'])?></strong><p><?=e($r['category'])?> <?=isset($r['published'])?($r['published']?'· Công khai':'· Bản nháp'):''?></p></div><div><a class="button small secondary" href="?tab=<?=$tab?>&edit=<?=$r['id']?>">Sửa</a> <a class="danger" href="?tab=<?=$tab?>&delete=<?=$r['id']?>">Xóa</a></div></div><?php endforeach;?></div>
<?php elseif($tab==='messages'):$rows=q('SELECT * FROM messages ORDER BY id DESC')->fetchAll();if(!$rows)echo '<div class="panel">Chưa có tin nhắn.</div>';foreach($rows as $r):?><article class="panel"><p class="eyebrow"><?=$r['is_read']?'ĐÃ ĐỌC':'TIN NHẮN MỚI'?> · <?=e($r['created_at'])?></p><h3><?=e($r['name'])?></h3><p><?=e($r['email'])?></p><p><?=nl2br(e($r['body']))?></p><?php if(!$r['is_read'])actionform('read',$r['id'],'Đánh dấu đã đọc');?> <a class="danger" href="?tab=messages&delete=<?=$r['id']?>">Xóa tin nhắn</a></article><?php endforeach;
elseif($tab==='password'):?><form method="post" class="panel"><?=csrf()?><input type="hidden" name="action" value="password"><?php field('old_password','Mật khẩu hiện tại','','password',200);field('new_password','Mật khẩu mới (ít nhất 12 ký tự)','','password',200);field('confirm_password','Nhập lại mật khẩu mới','','password',200);?><button>Đổi mật khẩu</button></form><?php endif;?>
<?php if(isset($_GET['delete'])&&in_array($tab,['projects','skills','messages'],true)):?><div class="panel"><h2>Xác nhận xóa mục #<?=(int)$_GET['delete']?>?</h2><p>Thao tác sẽ xóa vĩnh viễn mục này.</p><?php actionform('delete',(int)$_GET['delete'],'Xác nhận xóa');?> <a href="?tab=<?=$tab?>">Hủy</a></div><?php endif;?></main></div></body></html>
